using UnityEngine;using UnityEngine.EventSystems;
public class TouchControlCustomizer:MonoBehaviour{public ControlProfileManager profiles;public Canvas canvas;public CanvasGroup touchHud;public bool editMode;public void SetEditMode(bool on){editMode=on;}public void SetOpacity(float v){profiles.profile.touch.opacity=Mathf.Clamp01(v);if(touchHud)touchHud.alpha=v;}public void SetMoveDeadzone(float v)=>profiles.profile.touch.moveDeadzone=Mathf.Clamp01(v);public void SetLookDeadzone(float v)=>profiles.profile.touch.lookDeadzone=Mathf.Clamp01(v);public void ResetLayout(){profiles.ResetToDefault();Refresh();}public void Refresh(){if(touchHud)touchHud.alpha=profiles.profile.touch.opacity;foreach(var p in profiles.profile.touch.controls){var t=transform.Find(p.id) as RectTransform;if(t){t.anchorMin=t.anchorMax=p.anchor;t.sizeDelta=Vector2.one*p.size;}}}}
public class DraggableTouchControl:MonoBehaviour,IDragHandler{public TouchControlCustomizer customizer;RectTransform rt;void Awake()=>rt=transform as RectTransform;public void OnDrag(PointerEventData e){if(!customizer||!customizer.editMode)return;var rect=customizer.canvas.transform as RectTransform;RectTransformUtility.ScreenPointToLocalPointInRectangle(rect,e.position,e.pressEventCamera,out var local);Vector2 n=new Vector2(local.x/rect.rect.width+.5f,local.y/rect.rect.height+.5f);rt.anchorMin=rt.anchorMax=new Vector2(Mathf.Clamp01(n.x),Mathf.Clamp01(n.y));}}
